      "body": "<?xml version=\"1.0\" encoding=\"UTF-8\" ?>\n                        \n<ClinVarResult-Set><VariationArchive VariationID=\"587372\" VariationName=\"NM_004311.4(ARL3):c.445C&gt;T (p.Arg149Cys)\" VariationType=\"single nucleotide variant\" Accession=\"VCV000587372\" Version=\"6\" RecordType=\"classified\" NumberOfSubmissions=\"2\" NumberOfSubmitters=\"2\" DateLastUpdated=\"2026-02-15\" DateCreated=\"2018-11-05\" MostRecentSubmission=\"2026-02-15\">\n  <RecordStatus>current</RecordStatus>\n  <Species>Homo sapiens</Species>\n  <ClassifiedRecord>\n    <SimpleAllele AlleleID=\"578329\" VariationID=\"587372\">\n      <GeneList>\n        <Gene Symbol=\"ARL3\" FullName=\"ARF like GTPase 3\" GeneID=\"403\" HGNC_ID=\"HGNC:694\" Source=\"submitted\" RelationshipType=\"within single gene\">\n          <Location>\n            <CytogeneticLocation>10q24.32</CytogeneticLocation>\n            <SequenceLocation Assembly=\"GRCh38\" AssemblyAccessionVersion=\"GCF_000001405.38\" AssemblyStatus=\"current\" Chr=\"10\" Accession=\"NC_000010.11\" start=\"102673731\" stop=\"102714397\" display_start=\"102673731\" display_stop=\"102714397\" Strand=\"-\"/>\n            <SequenceLocation Assembly=\"GRCh37\" AssemblyAccessionVersion=\"GCF_000001405.25\" AssemblyStatus=\"previous\" Chr=\"10\" Accession=\"NC_000010.10\" start=\"104433483\" stop=\"104474189\" display_start=\"104433483\" display_stop=\"104474189\" Strand=\"-\"/>\n          </Location>\n          <OMIM>604695</OMIM>\n        </Gene>\n      </GeneList>\n      <Name>NM_004311.4(ARL3):c.445C&gt;T (p.Arg149Cys)</Name>\n      <CanonicalSPDI>NC_000010.11:102685871:G:A</CanonicalSPDI>\n      <VariantType>single nucleotide variant</VariantType>\n      <Location>\n        <CytogeneticLocation>10q24.32</CytogeneticLocation>\n        <SequenceLocation Assembly=\"GRCh38\" AssemblyAccessionVersion=\"GCF_000001405.38\" forDisplay=\"true\" AssemblyStatus=\"current\" Chr=\"10\" Accession=\"NC_000010.11\" start=\"102685872\" stop=\"1026